async function loadAdmin(tab=S.adminTab){if(!S.user||S.user.role!=='admin'||S.route!=='admin')return;S.adminTab=tab;if(['agents','risk-center','property-records','support-center','closing-management','offer-counters','lenders','email-alerts'].includes(tab)){try{await PREMIUM.loadAdminTab(tab);render();}catch(error){toast(error.message,true);}return;}if(['listing-checks','document-requests','reports','reviews','reviewer-security'].includes(tab))return TRUST.loadAdmin(tab).catch(error=>toast(error.message,true));if(tab==='verification'&&!S.verificationReviewKey){S.modal={kind:'verification-unlock'};renderOverlay();return;}try{if(tab==='overview')S.adminData.summary=await get('/admin/summary').then(j=>j);else if(tab==='properties')S.adminData.properties=await get('/admin/properties').then(j=>j.properties);else if(['tours','inquiries','offers'].includes(tab))S.adminData.items=await get('/admin/'+tab).then(j=>j.items);else if(tab==='messages'){S.adminData.conversations=await get('/admin/conversations').then(j=>j.items);if(S.selectedConv){S.adminData.messages=await get('/admin/conversations/'+S.selectedConv).then(j=>j.messages);}}else if(tab==='clients')S.adminData.users=await get('/admin/users').then(j=>j.users);else if(tab==='verification')S.adminData.verifications=await get('/admin/verifications').then(j=>j.users);else if(tab==='mls')S.adminData.mls=await get('/admin/mls');else if(tab==='transactions')S.adminData.transactions=await get('/admin/transactions').then(j=>j.items);else if(tab==='payments'){const x=await get('/admin/invoices');S.adminData.invoices=x.invoices;S.adminData.paypalConfigured=x.paypalConfigured;S.adminData.mode=x.mode;}render();if(tab==='messages')scrollBottom('admin-messages');}catch(e){if(tab==='verification'){S.verificationReviewKey='';S.adminData.verifications=[];S.modal={kind:'verification-unlock'};renderOverlay();}toast(e.message,true);}}
async function loadChat(){if(!S.chatOpen)return;try{const token=S.user?.role==='client'?null:localStorage.getItem('covalyn-chat-token');if(!token&&!S.user)return;const j=await get('/chat'+(token?'?token='+encodeURIComponent(token):''));S.chatMessages=j.messages||[];const el=document.getElementById('chat-messages');if(el){el.innerHTML=S.chatMessages.length?S.chatMessages.map(m=>bubble(m,m.sender==='client')).join(''):'<div class="bubble">Welcome! Leave us a message and our team can reply here.</div>';scrollBottom('chat-messages');}}catch{}}
