function formObj(form){return Object.fromEntries(new FormData(form).entries());}
async function submitForm(form){const what=form.dataset.form,b=formObj(form);
if(what==='quick-search'){S.filters={...S.filters,city:b.city||'',max:b.max||'',beds:b.beds||'Any',type:S.cat==='All'?'All types':S.cat,status:'Available'};S.cat='All';return navigate('catalog');}
if(what==='filters'){S.filters={city:b.city||'',max:b.max||'',beds:b.beds||'Any',type:b.type||'All types',status:b.status||'Available'};return render();}
if(what==='mortgage'){const o={};for(const k of ['price','down','rate','years','tax','insurance','hoa'])o[k]=Number(b[k]);if(o.price<10000||o.down<0||o.down>100||o.rate<0||o.years<1)return toast('Please enter realistic finance values.',true);document.getElementById('mortgage-result').innerHTML=calcDisplay(calcMonthly(o));return;}
if(what==='login'||what==='register'){const j=await post('/auth/'+what,what==='register'?{...b,consent:form.querySelector('[name=consent]').checked}:b);if(j.mfaRequired){S.pendingMfa=true;render();return;}S.user=j.user;S.authRegister=false;if(S.user.role==='client'&&S.fav.length){await Promise.allSettled(S.fav.filter(id=>S.properties.some(p=>p.id===id)).map(id=>post('/my/favorites/'+id,{})));}toast('Welcome to Covalyn Homes.');if(S.user.role==='admin'){S.adminTab='overview';navigate('admin');}else{S.portalTab='overview';navigate('portal');}return;}
if(what==='mfa-login'){const j=await post('/auth/mfa/complete-login',b);S.pendingMfa=false;S.user=j.user;toast('Signed in securely.');navigate(j.user.role==='admin'?'admin':'portal');return;}
if(what==='processing'){
 rememberProcessingForm(form);const draft=S.processingDraft,data=new FormData();
 for(const [name,value] of Object.entries(draft.values))data.set(name,String(value));
 for(const [name,file] of Object.entries(draft.files)){if(file.size>4*1024*1024)throw Error('Each document must be under 4 MB.');data.set(name,file,file.name);}
 await API('/my/processing',{method:'POST',body:data});clearProcessingDraft();toast('Your documents have been submitted for review.');return loadPortal();
}
if(what==='selling-inquiry'){
 await post('/inquiries',{...b,kind:'selling',contactConsent:form.querySelector('[name=contactConsent]').checked});form.reset();toast('Your property details have been sent. Our team will follow up with you.');return;
}
if(what==='verification-unlock'){S.verificationReviewKey=String(b.reviewKey||'');S.modal=null;renderOverlay();return loadAdmin('verification');}
if(what==='verification-review'){await patch('/admin/verifications/'+b.id,{status:b.status,note:b.note});toast('Review saved.');return loadAdmin('verification');}
if(what==='password'){await post('/auth/change-password',b);form.reset();return toast('Your password has been updated.');}
if(what==='inquiry'){await post('/inquiries',{...b,propertyId:b.propertyId||null});S.modal=null;renderOverlay();form.reset();return toast('Your inquiry has been sent to the Covalyn Homes team.');}
if(what==='tour'){await post('/tours',{...b,date:b.date,notes:b.notes||''});S.modal=null;renderOverlay();return toast('Your tour request has been sent for confirmation.');}
if(what==='offer'){await post('/offers',{...b,amount:b.amount});S.modal=null;renderOverlay();return toast('Your offer has been received for review.');}
if(what==='chat'){let token=S.user?.role==='client'?undefined:localStorage.getItem('covalyn-chat-token');if(!S.user&&!token){token=crypto.randomUUID();localStorage.setItem('covalyn-chat-token',token);}await post('/chat',{token,message:b.message,name:S.user?.name||'Guest visitor',email:S.user?.email||''});form.reset();await loadChat();return;}
if(what==='admin-reply'){if(!S.selectedConv)return;await post('/admin/conversations/'+S.selectedConv+'/reply',{message:b.message});form.reset();return loadAdmin('messages');}
if(what==='property'){const o={...b,lat:b.lat?Number(b.lat):null,lng:b.lng?Number(b.lng):null,price:Number(b.price),beds:Number(b.beds),baths:Number(b.baths),sqft:Number(b.sqft),lot_sqft:b.lot_sqft?Number(b.lot_sqft):null,year_built:b.year_built?Number(b.year_built):null,featured:b.featured==='on',features:b.features.split(',').map(x=>x.trim()).filter(Boolean),images:(S.adminData.properties||[]).find(p=>p.id===b.id)?.images||[]};const id=o.id,photos=Array.from(form.querySelector('[name=propertyPhotos]').files);if(photos.some(file=>file.size>4*1024*1024))throw Error('Each photo must be under 4 MB.');if(o.images.length+photos.length>24)throw Error('Use no more than 24 photos per property.');delete o.id;delete o.propertyPhotos;const saved=await (id?put('/admin/properties/'+id,o):post('/admin/properties',o));const propertyId=saved.property.id;let photoError='';for(const file of photos){try{const data=new FormData();data.append('image',file);await API('/admin/properties/'+propertyId+'/images',{method:'POST',body:data});}catch(error){photoError=error.message;break;}}S.modal=null;renderOverlay();toast(photoError?'Listing saved. A photo failed to upload: '+photoError:(id?'Property updated.':'Property created.'),Boolean(photoError));await loadProperties();return loadAdmin('properties');}
if(what==='upload'){const id=b.propertyId,file=form.querySelector('input[type=file]').files[0];if(!file)throw Error('Select an image first.');if(file.size>4*1024*1024)throw Error('Images must be under 4 MB.');const fd=new FormData();fd.append('image',file);const r=await API('/admin/properties/'+id+'/images',{method:'POST',body:fd});const p=propertyById(id);if(p)p.images=[...(p.images||[]),r.url];toast('Property photo uploaded.');openModal('upload',id);return loadAdmin('properties');}
if(what==='invoice-create'){
await post('/admin/invoices',{userId:b.userId,propertyId:b.propertyId||null,description:b.description,amount:b.amount});
S.modal=null;renderOverlay();toast('USD service invoice created for the buyer.');return loadAdmin('payments');
}
if(what==='transaction-create'){await post('/admin/transactions',b);S.modal=null;renderOverlay();toast('Purchase journey created.');return loadAdmin('transactions');}
if(what==='transaction-stage'){await patch('/admin/transactions/'+b.id,{stage:b.stage,note:b.note});S.modal=null;renderOverlay();toast('Milestone updated.');return loadAdmin('transactions');}
if(what==='payment'){await post('/admin/transactions/'+b.id+'/payments',{amount:b.amount,method:b.method,reference:b.reference,evidenceReference:b.evidenceReference});S.modal=null;renderOverlay();toast('Externally verified payment record saved.');return loadAdmin('transactions');}
}
async function handleForm(e){const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const btn=f.querySelector('button[type=submit]');const prev=btn?.innerHTML;if(btn){btn.disabled=true;btn.textContent='Working…';}try{await submitForm(f);}catch(err){toast(err.message||'Please try again.',true);}finally{if(btn&&btn.isConnected){btn.disabled=false;btn.innerHTML=prev;}}}
root.addEventListener('submit',handleForm);document.getElementById('overlays').addEventListener('submit',handleForm);
