async function boot(){Object.assign(S,discoverRoute());S.properties=[];S.preview=false;render();try{const [c,p,u,pay]=await Promise.allSettled([get('/config'),get('/properties'),get('/me'),get('/paypal/config')]);if(c.status==='fulfilled'){S.live=Boolean(c.value.live);S.mlsConfigured=Boolean(c.value.mlsConnected);S.mlsDisclaimer=c.value.mlsDisclaimer||'';}if(p.status==='fulfilled'){S.properties=p.value.properties||[];S.preview=false;}if(u.status==='fulfilled')S.user=u.value.user||null;if(pay.status==='fulfilled')S.paypalConfig=pay.value;render();if(S.user&&S.route==='portal')await loadPortal();if(S.user&&S.route==='admin')await loadAdmin(S.adminTab);TRUST.loadPublic().catch(()=>{});PREMIUM.loadPublic().catch(()=>{});if(S.route==='detail'&&S.live)post('/listings/'+S.detailId+'/view',{}).catch(()=>{});}catch(e){toast(e.message,true);}}
boot();
